import { Component, Prop, Vue } from 'vue-property-decorator';
import { OverlaysEventEmitter } from '../../event-emitter';
import { ILoadingSpinnerTranslations } from '../../translations';

@Component({
    name: 'LoadingSpinner'
})
export default class LoadingSpinner extends Vue {
    @Prop()
    protected translations: ILoadingSpinnerTranslations;

    public isVisible: boolean = false;
    public message: string = '';

    public created() {
        this.show = this.show.bind(this);
        this.hide = this.hide.bind(this);
    }

    public mounted() {
        OverlaysEventEmitter.on('showLoadingSpinner', this.show);
        OverlaysEventEmitter.on('hideLoadingSpinner', this.hide);
    }

    public beforeDestroy() {
        OverlaysEventEmitter.off('showLoadingSpinner', this.show);
        OverlaysEventEmitter.off('hideLoadingSpinner', this.hide);
    }

    private show(message?: string) {
        this.message = message || this.translations?.LOADING || 'Loading';
        this.isVisible = true;
    }

    private hide() {
        this.message = '';
        this.isVisible = false;
    }
}
